/// <summary>
/// AVA
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(CredManCustGuaranteeInsurance, CredManCustGuaranteeInsurance), FormDataSourceEventType::InitValue)]
public static void CredManCustGuaranteeInsurance_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
{
    CredManCustGuaranteeInsurance   record;
    record = sender.cursor();
    record.GuaranteeInsurance = CredManGuaranteeInsurance::Insurance;
    record.IncludeInExposure = NoYes::No;
}

/// <summary>
/// AVA
/// </summary>
/// <param name="sender">CredManCustGuaranteeInsurance</param>
/// <param name="e">ModifyFieldEventArgs</param>
[DataEventHandler(tableStr(CredManCustGuaranteeInsurance), DataEventType::ModifiedField)]
public static void CredManCustGuaranteeInsurance_onModifiedField(Common sender, DataEventArgs e)
{
    CredManCustGuaranteeInsurance custGuaranteeInsurance = sender as CredManCustGuaranteeInsurance;
    CredManInsuranceCoverageType  coverageType;

    ModifyFieldEventArgs modifyFieldEvent = e as ModifyFieldEventArgs;

    switch (modifyFieldEvent.parmFieldId())
    {
        case fieldNum(CredManCustGuaranteeInsurance, CoverageType):
            select firstonly coverageType where coverageType.recid == custGuaranteeInsurance.CoverageType;
            custGuaranteeInsurance.CreditLimitPercent = coverageType.CredManGuaranteeCreditLimitPercent;               
            break;
    }
}

/// <summary>
/// AVA reread caller
/// </summary>
/// <param name="sender">formRun</param>
/// <param name="e">FormEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormEventHandler(formStr(CredManCustGuaranteeInsurance), FormEventType::Closing)]
public static void CredManCustGuaranteeInsurance_OnClosing(xFormRun sender, FormEventArgs e)
{
    FormRun         callerFormRun = sender.args().caller();
    FormDataSource  callerFDS = callerformrun.datasource(formDataSourceStr(CustTable, CustTable));
    callerFDS.reread();
}
